-- Seed gerado a partir de site/data.js. Rode depois de schema.sql.

on conflict (slug) do update set title=excluded.title, tag=excluded.tag, date=excluded.date, image=excluded.image, excerpt=excluded.excerpt, body=excluded.body, featured=excluded.featured, sort=excluded.sort;

on conflict (id) do update set name=excluded.name, role=excluded.role, range=excluded.range, difficulty=excluded.difficulty, image=excluded.image, description=excluded.description, stats=excluded.stats, sort=excluded.sort;

on conflict (key) do nothing;
